  const int64_t sYn = (int64_t)Cout * sYc;
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win),
      make_stride(sXc, sXh, Int<1>{}));
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{}));
  // weight layout: (Cin, out_per_group, kH, kW) - PyTorch ConvTranspose2d layout
  const int64_t sWic = (int64_t)out_per_group * kH * kW;
  const int64_t sWoc = (int64_t)kH * kW;
  const int64_t sWkh = (int64_t)kW;
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cin, out_per_group, kH, kW),
      make_stride(sWic, sWoc, sWkh, Int<1>{}));
  extern __shared__ float smem_raw[];
  auto sW = make_tensor(
      make_smem_ptr(smem_raw),
      make_shape(in_per_group, CcPerBlock, kH, kW),
      make_stride((int64_t)CcPerBlock * kH * kW, (int64_t)kH * kW, (int64_t)kW, Int<1>{}));
  const int total_w = in_per_group * CcPerBlock * kH * kW;
  for (int idx = tid; idx < total_w; idx += Threads) {
    int rem = idx;
    int kw = rem % kW; rem /= kW;
    int kh = rem % kH; rem /= kH;
    int cc = rem % CcPerBlock; rem /= CcPerBlock;
    int icl = rem;
    int oc_local = oc_base_local + cc;
    float wval = 0.0f;
    if (oc_local < out_per_group) {
