      wval = (float) mW(ic_global, oc_local, kh, kw);
    }
    sW(icl, cc, kh, kw) = wval;
  }
  int ow_idx[PVec];
  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    ow_idx[i] = ow_block + tid + i * Threads;
  }
  // Determine the input-row span needed for this block's single output row.
  int ih_min = INT_MAX;
  int ih_max = INT_MIN;
  for (int kh = 0; kh < kH; ++kh) {
    int num = oh + pad_h - kh * dil_h;
    int val = (num >= 0) ? (num / stride_h) : -(((-num) + stride_h - 1) / stride_h);
    if (val < ih_min) ih_min = val;
    if (val > ih_max) ih_max = val;
  }
