cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <climits>

using namespace cute;

template <typename T>
__global__ void conv_transpose2d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ Bias,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int Cout, int kH, int kW,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups,
    int Hout, int Wout,
    int in_per_group, int out_per_group,
    int CcPerBlock, int channel_tiles)
{
  constexpr int Threads = 128;
  constexpr int PVec    = 2;
  constexpr int CC_MAX  = 16;
  const int tid = threadIdx.x;
  const int n  = blockIdx.z;
  const int gy = blockIdx.y;
  const int oh = gy % Hout;
  const int rest = gy / Hout;
  const int g  = rest / channel_tiles;
  const int c_tile = rest % channel_tiles;
  const int oc_base_local = c_tile * CcPerBlock;
  const int PTile   = Threads * PVec;
  const int ow_block = blockIdx.x * PTile;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sXn = (int64_t)Cin * sXc;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  const int64_t sYn = (int64_t)Cout * sYc;
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win),
      make_stride(sXc, sXh, Int<1>{}));
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{}));
  // weight layout: (Cin, out_per_group, kH, kW) - PyTorch ConvTranspose2d layout
  const int64_t sWic = (int64_t)out_per_group * kH * kW;
  const int64_t sWoc = (int64_t)kH * kW;
  const int64_t sWkh = (int64_t)kW;
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cin, out_per_group, kH, kW),
      make_stride(sWic, sWoc, sWkh, Int<1>{}));
  extern __shared__ float smem_raw[];
  auto sW = make_tensor(
      make_smem_ptr(smem_raw),
      make_shape(in_per_group, CcPerBlock, kH, kW),
      make_stride((int64_t)CcPerBlock * kH * kW, (int64_t)kH * kW, (int64_t)kW, Int<1>{}));
  const int total_w = in_per_group * CcPerBlock * kH * kW;
  for (int idx = tid; idx < total_w; idx += Threads) {
    int rem = idx;
    int kw = rem % kW; rem /= kW;
    int kh = rem % kH; rem /= kH;
    int cc = rem % CcPerBlock; rem /= CcPerBlock;
    int icl = rem;
    int oc_local = oc_base_local + cc;
    float wval = 0.0f;
    if (oc_local < out_per_group) {
      int ic_global = g * in_per_group + icl;
      wval = (float) mW(ic_global, oc_local, kh, kw);
    }
    sW(icl, cc, kh, kw) = wval;
  }
  int ow_idx[PVec];
  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    ow_idx[i] = ow_block + tid + i * Threads;
  }
  // Determine the input-row span needed for this block's single output row.
  int ih_min = INT_MAX;
  int ih_max = INT_MIN;
  for (int kh = 0; kh < kH; ++kh) {
    int num = oh + pad_h - kh * dil_h;
    int val = (num >= 0) ? (num / stride_h) : -(((-num) + stride_h - 1) / stride_h);
    if (val < ih_min) ih_min = val;
    if (val > ih_max) ih_max = val;
  }
  if (ih_min < 0) ih_min = 0;
  if (ih_max > H - 1) ih_max = H - 1;
  if (ih_max < ih_min) ih_max = ih_min - 1;
  int ih_range = ih_max - ih_min + 1;
  if (ih_range < 0) ih_range = 0;
  // Determine the input-col span needed for this block's output-column tile.
  int ow_lo = ow_block;
  int ow_hi = ow_block + PTile - 1;
  if (ow_hi >= Wout) ow_hi = Wout - 1;
  if (ow_hi < ow_lo) ow_hi = ow_lo;
  int iw_min = INT_MAX;
  int iw_max = INT_MIN;
  for (int kw = 0; kw < kW; ++kw) {
    int num_lo = ow_lo + pad_w - kw * dil_w;
    int num_hi = ow_hi + pad_w - kw * dil_w;
    int lo = (num_lo >= 0) ? (num_lo / stride_w) : -(((-num_lo) + stride_w - 1) / stride_w);
    int hi = (num_hi >= 0) ? (num_hi / stride_w) : -(((-num_hi) + stride_w - 1) / stride_w);
    if (lo < iw_min) iw_min = lo;
    if (hi > iw_max) iw_max = hi;
  }
  if (iw_min < 0) iw_min = 0;
  if (iw_max > Win - 1) iw_max = Win - 1;
  if (iw_max < iw_min) iw_max = iw_min - 1;
  int iw_range = iw_max - iw_min + 1;
  if (iw_range < 0) iw_range = 0;
  float* sX = smem_raw + total_w;
  const int64_t sXc_local = (int64_t)ih_range * iw_range;
  int total_x = in_per_group * ih_range * iw_range;
  for (int idx = tid; idx < total_x; idx += Threads) {
    int rem = idx;
    int iw_local = rem % iw_range; rem /= iw_range;
    int ih_local = rem % ih_range; rem /= ih_range;
    int icl = rem;
    int ih_global = ih_min + ih_local;
    int iw_global = iw_min + iw_local;
    int ic_global = g * in_per_group + icl;
    float xval = 0.0f;
    if (ih_global >= 0 && ih_global < H && iw_global >= 0 && iw_global < Win) {
      xval = (float)(X[(int64_t)n * sXn + (int64_t)ic_global * sXc + (int64_t)ih_global * sXh + iw_global]);
    }
    sX[(int64_t)icl * sXc_local + (int64_t)ih_local * iw_range + iw_local] = xval;
  }
  __syncthreads();
  float acc[CC_MAX][PVec];
  #pragma unroll
  for (int cc = 0; cc < CC_MAX; ++cc) {
    #pragma unroll
    for (int i = 0; i < PVec; ++i) acc[cc][i] = 0.0f;
  }
  if (Bias != nullptr) {
    for (int cc = 0; cc < CcPerBlock; ++cc) {
      int oc_local = oc_base_local + cc;
      if (oc_local >= out_per_group) continue;
      int oc_global = g * out_per_group + oc_local;
      float bval = (float) Bias[oc_global];
      #pragma unroll
      for (int i = 0; i < PVec; ++i) {
        if (ow_idx[i] < Wout) acc[cc][i] = bval;
      }
    }
  }
  for (int kh = 0; kh < kH; ++kh) {
    int ih_num0 = oh + pad_h - kh * dil_h;
    if (ih_num0 % stride_h != 0) continue;
    int ih = ih_num0 / stride_h;
    if (ih < 0 || ih >= H) continue;
    int ih_local = ih - ih_min;
    if (ih_local < 0 || ih_local >= ih_range) continue;
    for (int kw = 0; kw < kW; ++kw) {
      #pragma unroll
      for (int i = 0; i < PVec; ++i) {
        int ow = ow_idx[i];
        if (ow >= Wout) continue;
        int iw_num = ow + pad_w - kw * dil_w;
        if (iw_num % stride_w != 0) continue;
        int iw = iw_num / stride_w;
        if (iw < 0 || iw >= Win) continue;
        int iw_local = iw - iw_min;
        if (iw_local < 0 || iw_local >= iw_range) continue;
        for (int icl = 0; icl < in_per_group; ++icl) {
          float xval = sX[(int64_t)icl * sXc_local + (int64_t)ih_local * iw_range + iw_local];
          for (int cc = 0; cc < CcPerBlock; ++cc) {
            float wval = sW(icl, cc, kh, kw);
            acc[cc][i] += xval * wval;
          }
        }
      }
    }
  }
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int oc_local = oc_base_local + cc;
    if (oc_local >= out_per_group) continue;
    int oc_global = g * out_per_group + oc_local;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int ow = ow_idx[i];
      if (ow >= Wout) continue;
      mY(oc_global, oh, ow) = static_cast<T>(acc[cc][i]);
    }
  }
}

torch::Tensor conv_transpose2d_forward(
    torch::Tensor x,
    torch::Tensor w,
    c10::optional<torch::Tensor> b,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups)
{
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N,C,H,W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cin, Cout/groups, kH, kW]");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  int64_t N   = x_c.size(0);
  int64_t Cin = x_c.size(1);
  int64_t H   = x_c.size(2);
  int64_t Win = x_c.size(3);

  int64_t out_per_group = w_c.size(1);
  int64_t kH = w_c.size(2);
  int64_t kW = w_c.size(3);
  TORCH_CHECK(w_c.size(0) == Cin, "weight.size(0) must equal in_channels");

  int64_t Cout = out_per_group * groups;
  int64_t in_per_group = Cin / groups;
  TORCH_CHECK(in_per_group * groups == Cin, "Cin must be divisible by groups");

  int64_t Hout = (H - 1) * stride_h - 2 * pad_h + dil_h * (kH - 1) + 1;
  int64_t Wout = (Win - 1) * stride_w - 2 * pad_w + dil_w * (kW - 1) + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size");

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value() && b.value().defined()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.scalar_type() == at::kFloat, "bias must be float32");
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Hout, Wout}, x_c.options());

  constexpr int Threads = 128;
  constexpr int PVec = 2;
  constexpr int CC_MAX = 16;

  int CcPerBlock = (int)std::min<int64_t>(out_per_group, CC_MAX);
  int channel_tiles = (int)((out_per_group + CcPerBlock - 1) / CcPerBlock);

  int64_t PTile = Threads * PVec;
  int blocks_x = (int)((Wout + PTile - 1) / PTile);
  dim3 block(Threads);
  dim3 grid(blocks_x, (unsigned)(Hout * groups * channel_tiles), (unsigned)N);
  size_t shmem_w_bytes = (size_t)in_per_group * CcPerBlock * kH * kW * sizeof(float);
  int64_t ihTileSize = ((int64_t)(kH - 1) * dil_h) / stride_h + 3;
  if (ihTileSize < 1) ihTileSize = 1;
  if (ihTileSize > H) ihTileSize = H;
  int64_t maxOwSpan = std::min<int64_t>(PTile, Wout);
  int64_t iwTileSize = (maxOwSpan - 1 + (int64_t)(kW - 1) * dil_w) / stride_w + 3;
  if (iwTileSize < 1) iwTileSize = 1;
  if (iwTileSize > Win) iwTileSize = Win;
  size_t shmem_x_bytes = (size_t)in_per_group * (size_t)ihTileSize * (size_t)iwTileSize * sizeof(float);
  size_t shmem_bytes = shmem_w_bytes + shmem_x_bytes;
  if (shmem_bytes > 48 * 1024) {
    cudaFuncSetAttribute(
        conv_transpose2d_kernel<float>,
        cudaFuncAttributeMaxDynamicSharedMemorySize,
        (int)shmem_bytes);
  }

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv_transpose2d_kernel<float><<<grid, block, shmem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)H, (int)Win,
      (int)Cout, (int)kH, (int)kW,
      stride_h, stride_w,
      pad_h, pad_w,
      dil_h, dil_w,
      groups,
      (int)Hout, (int)Wout,
      (int)in_per_group, (int)out_per_group,
      CcPerBlock, channel_tiles
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv_transpose2d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
